const data = msg.payload;

if (!data || typeof data !== 'object' || Array.isArray(data)) {
    node.warn('Payload bukan object JSON');
    return null;
}

function validText(value) {
    return typeof value === 'string' && value.trim() !== '';
}

function validNumber(value) {
    return value !== null && value !== '' && Number.isFinite(Number(value));
}

function normalizeStatus(value) {
    const status = String(value || '').toUpperCase();
    return status === 'ON' || status === 'OFF' ? status : null;
}

function requireNumbers(fields) {
    for (const field of fields) {
        if (!validNumber(data[field])) {
            node.warn(`Parameter ${field} tidak valid pada ${data.node_id || 'unknown'}`);
            return false;
        }
    }
    return true;
}

if (!validText(data.group_id) || !validText(data.node_id)) {
    node.warn('group_id atau node_id tidak tersedia');
    return null;
}

const groupId = data.group_id.trim();
const nodeId = data.node_id.trim();
const sequenceNo = validNumber(data.sequence) ? Number(data.sequence) : 0;
const uptimeMs = validNumber(data.uptime_ms) ? Number(data.uptime_ms) : 0;
const machineStatus = normalizeStatus(data.machine_status);

if (!machineStatus) {
    node.warn('machine_status harus ON atau OFF');
    return null;
}

msg.mqtt_topic = msg.topic || '';
msg.group_id = groupId;
msg.node_id = nodeId;

switch (nodeId) {
    case 'node-perikanan':
    case 'node-kolam': {
        if (!requireNumbers(['do_mg_l', 'ph', 'water_temp_c', 'ammonia_mg_l'])) return null;
        const aeratorStatus = normalizeStatus(data.aerator_status) || machineStatus;
        msg.topic = 'INSERT INTO aquaponic_fisheries (group_id,node_id,sequence_no,uptime_ms,machine_status,do_mg_l,ph,water_temp_c,ammonia_mg_l,aerator_status) VALUES (?,?,?,?,?,?,?,?,?,?)';
        msg.payload = [groupId,nodeId,sequenceNo,uptimeMs,machineStatus,Number(data.do_mg_l),Number(data.ph),Number(data.water_temp_c),Number(data.ammonia_mg_l),aeratorStatus];
        msg.data_category = 'fisheries';
        break;
    }

    case 'node-hidroponik': {
        if (!requireNumbers(['ph', 'tds_ppm', 'water_temp_c', 'water_level_pct'])) return null;
        const pumpStatus = normalizeStatus(data.pump_status) || machineStatus;
        msg.topic = 'INSERT INTO aquaponic_hydroponics (group_id,node_id,sequence_no,uptime_ms,machine_status,ph,tds_ppm,water_temp_c,water_level_pct,pump_status) VALUES (?,?,?,?,?,?,?,?,?,?)';
        msg.payload = [groupId,nodeId,sequenceNo,uptimeMs,machineStatus,Number(data.ph),Number(data.tds_ppm),Number(data.water_temp_c),Number(data.water_level_pct),pumpStatus];
        msg.data_category = 'hydroponics';
        break;
    }

    case 'node-energi':
    case 'node-solar': {
        if (!requireNumbers(['pv_power_w', 'battery_soc_pct', 'battery_voltage_v', 'load_power_w', 'energy_kwh'])) return null;
        msg.topic = 'INSERT INTO aquaponic_energy (group_id,node_id,sequence_no,uptime_ms,machine_status,pv_power_w,battery_soc_pct,battery_voltage_v,load_power_w,energy_kwh) VALUES (?,?,?,?,?,?,?,?,?,?)';
        msg.payload = [groupId,nodeId,sequenceNo,uptimeMs,machineStatus,Number(data.pv_power_w),Number(data.battery_soc_pct),Number(data.battery_voltage_v),Number(data.load_power_w),Number(data.energy_kwh)];
        msg.data_category = 'energy';
        break;
    }

    default:
        node.warn(`node_id tidak dikenali: ${nodeId}`);
        return null;
}

node.status({fill:'green',shape:'dot',text:`${groupId} / ${nodeId}`});
return msg;
